export function resolveIconSvgSheetText(sheetName: string) { 
    switch (sheetName) {
        case 'sprite':
            return sprite
        case 'sprite-ph-base':
            return spritePhBase
        case 'sprite-ph-fill':
            return spritePhFill
        case 'sprite-ph-light':
            return spritePhLight
    }
}